mapper.select:
SELECT 
FROM contents c


LIMIT #{query.size} OFFSET #{query.offset}

SELECT 
FROM contents c
WHERE c.status = 'PUBLISHED'
  AND c.id != #{id}
  AND (
      c.published_at < #{publishedAt}
      OR (c.published_at = #{publishedAt} AND c.id < #{id})
  )
ORDER BY c.published_at DESC, c.id DESC
LIMIT 1

SELECT 
FROM contents c
WHERE c.status = 'PUBLISHED'
  AND c.id != #{id}
  AND (
      c.published_at > #{publishedAt}
      OR (c.published_at = #{publishedAt} AND c.id > #{id})
  )
ORDER BY c.published_at ASC, c.id ASC
LIMIT 1

SELECT , ( ( SELECT COUNT(*) FROM content_tag ct WHERE ct.content_id = c.id AND ct.tag_id IN ( SELECT tag_id FROM content_tag WHERE content_id = #{contentId} ) ) * 3 + ( SELECT COUNT(*) FROM content_category cc WHERE cc.content_id = c.id AND cc.category_id IN ( SELECT category_id FROM content_category WHERE content_id = #{contentId} ) ) * 2 + CASE WHEN c.type = #{currentType} THEN 1 ELSE 0 END ) AS relation_score FROM contents c WHERE c.status = 'PUBLISHED' AND c.id != #{contentId}
AND c.id NOT IN
#{excludedId}
HAVING relation_score > 0 ORDER BY relation_score DESC, c.published_at DESC, c.id DESC LIMIT #{limit}

SELECT 
FROM contents c


LIMIT #{query.size} OFFSET #{query.offset}

SELECT 
FROM contents c
WHERE c.id = #{id}

SELECT COUNT(*)
FROM contents
WHERE slug = #{slug}

    AND id != #{excludeId}
